/**
 * @summary Run an import for a category + city
 */
export const getRunImportUrl = () => {
  return `/api/imports/run`;
};

export const runImport = async (
  importRequest: ImportRequest,
  options?: RequestInit,
): Promise<ImportResult> => {
  return customFetch<ImportResult>(getRunImportUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(importRequest),
  });
};

export const getRunImportMutationOptions = <
  TError = ErrorType<ErrorResponse>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof runImport>>,
    TError,
    { data: BodyType<ImportRequest> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof runImport>>,
  TError,
  { data: BodyType<ImportRequest> },
  TContext
> => {
  const mutationKey = ["runImport"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof runImport>>,
    { data: BodyType<ImportRequest> }
  > = (props) => {
    const { data } = props ?? {};

    return runImport(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type RunImportMutationResult = NonNullable<
  Awaited<ReturnType<typeof runImport>>
>;
export type RunImportMutationBody = BodyType<ImportRequest>;
export type RunImportMutationError = ErrorType<ErrorResponse>;

/**
 * @summary Run an import for a category + city
 */
export const useRunImport = <
  TError = ErrorType<ErrorResponse>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof runImport>>,
    TError,
    { data: BodyType<ImportRequest> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof runImport>>,
  TError,
  { data: BodyType<ImportRequest> },
  TContext
> => {
  return useMutation(getRunImportMutationOptions(options));
};

